"""Test block BarChart (Charts): A bar chart to compare amounts across categories or days, grouped side by side or stacked into a total.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/charts/BarChart.md and its markup
(kit/blocks/charts/BarChart.html, kit/blocks/charts/BarChart.2.html; source fff3d17e9264), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  Then the chart {title} is described as {text}
  When I show the chart {title} as a table
  Then the chart {title} row {label} shows {value}
  Then the chart {title} is in the {state} state
States (from the card): Loaded, Loading, Empty, Error, Grouped or stacked, Horizontal, Many categories, Hover /
touch on a point, Legend item, Theme change. Checked by the state step: Loaded, Loading, Empty, Error.
"""
from __future__ import annotations

from functional import Registry
from functional import primitives as p

BLOCK = "BarChart"
ROUTE = ""
STATES = ["Loaded", "Loading", "Empty", "Error", "Grouped or stacked", "Horizontal", "Many categories", "Hover / touch on a point", "Legend item", "Theme change"]
DEFAULT_STATE = "Loaded"
CHECKED_STATES = ["Loaded", "Loading", "Empty", "Error"]
DEMO = ["kit/blocks/charts/BarChart.html"]
SELF_TEST = [
    "Then the chart \"Orders per day\" is described as \"Saturday is busiest\"",
    "Then the chart \"Orders per day\" is in the \"Loaded\" state",
    "When I show the chart \"Orders per day\" as a table",
    "Then the chart \"Orders per day\" row Sat shows 83",
]

steps = Registry(block=BLOCK)


class BarChart:
    """The BarChart block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def card(self, title):
        return p.control(self.page, role="region", name=str(title), block=BLOCK)

    def chart(self, title):
        return p.control(self.card(title), role="img", block=BLOCK)

    def chart_all(self, title):
        """Every match, possibly none (for counting)."""
        return self.card(title).get_by_role("img")

    def loading(self, title):
        return p.control(self.card(title), css="[aria-busy=\"true\"]", block=BLOCK)

    def alert(self, title):
        return p.control(self.card(title), role="alert", block=BLOCK)

    def table_toggle(self, title):
        return p.control(self.card(title), text="Show as a table", block=BLOCK)

    def table_row(self, title, label):
        return p.control(self.card(title), role="row", name=str(label), block=BLOCK)

    def expect_state(self, state: str, title) -> None:
        """Check one of the card's states: Loaded, Loading, Empty, Error."""
        b = self
        if state == "Loaded":
            p.expect_visible(b.chart(title))
        elif state == "Loading":
            p.expect_visible(b.loading(title).first)
        elif state == "Empty":
            p.expect_count(b.chart_all(title), 0)
        elif state == "Error":
            p.expect_visible(b.alert(title).first)
        else:
            raise AssertionError(f"BarChart has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("Then the chart {title} is described as {text}", level="e2e")
def then_the_chart_title_is_described_as_text(world, title, text):
    b = BarChart(world.page, getattr(world, "base_url", ""))
    p.expect_name(b.chart(title), str(text))


@steps.step("When I show the chart {title} as a table", level="e2e")
def when_i_show_the_chart_title_as_a_table(world, title):
    b = BarChart(world.page, getattr(world, "base_url", ""))
    p.click(b.table_toggle(title))


@steps.step("Then the chart {title} row {label} shows {value}", level="e2e")
def then_the_chart_title_row_label_shows_value(world, title, label, value):
    b = BarChart(world.page, getattr(world, "base_url", ""))
    p.expect_text(b.table_row(title, label), str(value))


@steps.step("Then the chart {title} is in the {state} state", level="e2e")
def then_the_chart_title_is_in_the_state_state(world, title, state):
    b = BarChart(world.page, getattr(world, "base_url", ""))
    b.expect_state(state, title)
